  [94356] = { "Craftsman's Writ: Felcloth Boots", "依頼主が求める品を手に入れ、地図に記された場所へ届けてください。取引を完了するには、この依頼書を所持している必要があります。", "<色あせたインクで書かれたこのメモには、Felcloth Bootsを$N1個求める依頼が、届け先と支払いについての情報とともに記されている。一番下には、この証書は譲渡可能である旨が記されている。>", nil, nil, 0xa572ff0f, 0x89b8e7e5, 0xe337cbad, nil, nil, "...mm" },
  [94357] = { "Craftsman's Writ: Cenarion Herb Bag", "依頼主が求める品を手に入れ、地図に記された場所へ届けてください。取引を完了するには、この依頼書を所持している必要があります。", "<色あせたインクで書かれたこのメモには、Cenarion Herb Bagを$N1個求める依頼が、届け先と支払いについての情報とともに記されている。一番下には、この証書は譲渡可能である旨が記されている。>", nil, nil, 0x69c4d25e, 0x89b8e7e5, 0x3af81970, nil, nil, "...mm" },
  [94358] = { "Craftsman's Writ: Shadoweave Mask", "依頼主が求める品を手に入れ、地図に記された場所へ届けてください。取引を完了するには、この依頼書を所持している必要があります。", "<色あせたインクで書かれたこのメモには、Shadoweave Maskを$N1個求める依頼が、届け先と支払いについての情報とともに記されている。一番下には、この証書は譲渡可能である旨が記されている。>", nil, nil, 0x98796734, 0x89b8e7e5, 0xcc7dfbdd, nil, nil, "...mm" },
  [94359] = { "Craftsman's Writ: Ghostweave Vest", "依頼主が求める品を手に入れ、地図に記された場所へ届けてください。取引を完了するには、この依頼書を所持している必要があります。", "<色あせたインクで書かれたこのメモには、Ghostweave Vestを$N1個求める依頼が、届け先と支払いについての情報とともに記されている。一番下には、この証書は譲渡可能である旨が記されている。>", nil, nil, 0x8cf903cf, 0x89b8e7e5, 0x8ace6ad3, nil, nil, "...mm" },
  [94360] = { "Craftsman's Writ: Soul Pouch", "依頼主が求める品を手に入れ、地図に記された場所へ届けてください。取引を完了するには、この依頼書を所持している必要があります。", "<色あせたインクで書かれたこのメモには、Soul Pouchを$N1個求める依頼が、届け先と支払いについての情報とともに記されている。一番下には、この証書は譲渡可能である旨が記されている。>", nil, nil, 0xbdabef1c, 0x89b8e7e5, 0x0b60ca87, nil, nil, "...mm" },
  [94369] = { "Zephrasの運命", "ValanaarのTalaanis Shadowsongと話してください。", "Ansiremからエレメンタルの王たちについて多くを聞いたが、Zephrasを隠していた守りが消えた今、Al'Akirを恐れる十分な理由があるのではないかと心配している。もしWindlordが我々を攻めると決めたら、彼の領域にいるここでは、身を守る術はまったくない。\n\nHigh Elder Shadowsongは我々が置かれている危険を知る必要がある。そして何より、Azerothへの任務で我々が何を目指しているのかをだ。我々は故郷を救う手立てを見つけ出す。誓おう。", nil, nil, 0x6d3ea2fe, 0x4440ff8a, 0xbee20486, nil, nil, "...mm" },
  [94373] = { "大地の呼び声", "Frostmane Bear Pendantsを2つ、AnvilmarのTeo Hammerstormに届けてください。", "うむ、その時が来たぞ、若きシャーマンよ。お前さんは足元の岩のように頑丈にたくましく育った。シャーマンの道を選んだこと自体、まだ己を証明する前から山の知恵を持っとる証だ。大地の道を歩むだけの、岩のような根性がお前さんにはある。\n\nだが大地の加護を得るには、きちんと向き合わねばならん。ここから南に、Frostmaneのトロールどもが洞窟に住んでおる。\n\n奴らが身につけとる首飾りを2つ持ってこい。Iceclawの熊から作られたものだ。そうしたら、お前さんの今後についてもっと話そう。", nil, nil, 0xe316c17f, 0xc897beee, 0x7da2ad26, nil, nil, "...mm" },
  [94374] = { "大地の呼び声", "Spirit Stoneを見つけ、Earth Saptaを飲んでください。", "うむ、saptaってのは魔法で作られた薬でな、わしらの魂を精霊と結びつけるものだ。そのレシピを知っとるシャーマンはほんの一握りで、意志の弱い者には向かん。飲めば、他の者には見えんものが見える。肝に銘じておけ。神聖な場所でしか飲んではならん。\n\n北のSpirit Stoneへ向かえ。山を登る隠れた道の突き当たりにひっそりとある。そこで飲むのだ……大地がお前さんに見せるものを見てこい。", nil, nil, 0xe316c17f, 0x4c31146f, 0x28284db1, nil, nil, "...mm" },
  [94375] = { "大地の呼び声", "Rough QuartzをAnvilmarのTeo Hammerstormに届けてください。", "このrough quartzを持って行き、わしと会った証としてTeo Hammerstormに渡すのだ。奴がお前さんのためにトーテムを作ってくれる。この小石がその心臓となる。小さく見えるかもしれんが、大きさなど問題ではないこと、どんなに小さなものでも多くのものより長く残りうることを、お前さんもいずれ知るだろう。\n\n辛抱するのだ、{name}。強くあれ。そして知恵を求めよ。それが大地がお前さんに求めるものだ。最後には、お前さんは大地とひとつになる。大地を敬え。大地もお前さんを敬うだろう。", nil, nil, 0xe316c17f, 0x1c898e3e, 0x1415c33d, nil, nil, "...mm" },
  [94411] = { "お節介なメイジたち", "Shen'dar HighlandsでHigh Order Apprenticesを6体倒してください。", "気をつけて。村の北にある立石のあたりでHigh Orderの者たちが目撃されています。我々の聖地に手出しするなと何度も警告してきましたが、彼らはますます大胆に我々を圧迫してきています。立石のところへ行って彼らを追い散らし、あなたの決意を我々に示してください。\n\nあからさまな流血を認めるのは気が進みませんが、追い払うためにはやるべきことをやってください。済んだら私のところへ戻ってきてください。", nil, nil, 0xf63c825c, 0xff42e97b, 0x399d9347, nil, nil, "...mm" },
  [94413] = { "魔法による侮辱", "Shen'dar HighlandsでWindshaper Novice Seersを6体倒してください。", "最近Zephrasの地表にレイラインが現れたことは、我らの結社にとって大きな意味を持っている。この地に満ちるエネルギーに、より直接的で確かな形で触れられるようになり、その魔法への理解は大いに深まった。\n\nしかしWindshapersは、これらの出現を「癒やす」べき大地の傷跡とみなしている。これは我らの結社への侮辱であり、とうてい容認できるものではない。\n\n南西の森にあるレイラインへ行き、そこにいるWindshapersを追い払ってくれ。", nil, nil, 0x28568d0e, 0x3affac9b, 0x795cdf90, nil, nil, "...mm" },
  [94414] = { "Zephrasの錨", "Halaan Hawk-Eyeと話し、彼の力を借りて遠くの錨の塔を見てください。", "ごきげんよう、若き{name}。私はよくここに来て、古のanchor pylonを眺めているのです。風の精霊たちからの贈り物で、それらが私たちの島を結びつけ、支えています。けれども近頃、その魔法が不安定でむらのあるものになってきました。\n\n私に見える限り、苦しんでいる様子はありません。その輝きも変わっていません。\n\nよろしければ、あなた自身の目で見られるよう、私の力をお貸ししましょう。", nil, nil, 0x238731a9, 0x1acadf70, 0x9ea9c243, nil, nil, "...mm" },
  [94427] = { "神性の教え", "UndercityのTanis Alderwoodと話してください。", "パラディンであることの重要な信条のひとつは、神性の追求だ。これは神になることの追求ではなく、ただ善そのものを、善のために追い求めることだ。我々は皆、何らかの悲劇を経てこの場所にたどり着いた。生前の我々をパラディンたらしめていたあの恩寵を失うのはたやすいことだろう。\n\nUndercityへ行き、Trade QuarterでTanis Alderwoodを探せ。彼らは困っていて、恩寵を大いに必要としているかもしれない。", nil, nil, 0x58def706, 0xf413a91f, 0xecaf8eb7, nil, nil, "...mm" },
  [94434] = { "神性の教え", "Linen Clothを10枚、UndercityのTanis Alderwoodに届けてください。", "待ってくれ、あんたが……助けてくれるって？ なんでパラディンが俺みたいな物乞いを助けたいんだ？\n\nまあ、少しは手を貸してもらえるかもしれないな。\n\n女房のことなんだ。あいつは、その……ばらばらになりかけてる。文字通りの意味でな。薬師たちならすっかり元通りに縫い合わせてくれるんだが、みんなDark Ladyの仕事にかかりきりで、手の空いてる者がいない。新しい布を持ってきてくれたら、薬師を待つあいだ、せめて体をまとめておく包帯くらいは作ってやれるんだが。", nil, nil, 0x58def706, 0xde430c6a, 0x712cb595, nil, nil, "...mm" },
  [94435] = { "神性の教え", "Bandarion KeepのDanitha Morrのところへ戻ってください。", "なんでわざわざ俺を助けてくれるのかわからないが、ありがたく思ってる。誰かにここへ寄こされたんなら、そいつにも感謝してると伝えてくれ。Tanis Alderwoodはいつでもあんたの友だ、{class}。", nil, nil, 0x58def706, 0x4528f784, 0xb51d252f, nil, nil, "...mm" },
  [94436] = { "神性の教え", "Bandarion KeepのDeathguard Billmuthと話してください。\n\nSymbol of Lifeをなくしてしまったら、Danitha Morrのところへ戻れば代わりをもらえます。", "光の最も偉大な賜物のひとつを導く力を示す時だ。\n\n今渡した品はSymbol of Lifeという。気をつけろ。このような光の護符を扱うのは、少々苦痛を伴うかもしれない。光は我々を生み出した力にとっては忌むべきものかもしれないが、それでも我々の導き手であり味方だ。痛みがそれを思い出させてくれる。\n\n下の階のDeathguard Billmuthに会いに行け。彼は着いたばかりで、我々に助けを求めてきた。真のパラディンに何ができるか、彼とForsakenに見せてやれ。", nil, nil, 0x58def706, 0x5c7b44af, 0xb27ae887, nil, nil, "...mm" },
  [94438] = { "神性の教え", "Symbol of Lifeを持っていき、それを使ってVenomweb ValeでDeathguard Falganを蘇生させてください。\n\nSymbol of Lifeをなくしてしまったら、Danitha Morrのところへ戻れば代わりをもらえます。", "Falganと俺は、Venomweb Valeでのscarletの動きを偵察する任務に就いていた。奴らの野営地のひとつに十分近づいて、Brillへの攻撃に関する新しい命令を聞き出すことができた。だが次にどうするか決める前に、俺が小枝を踏んで、その音で奴らに気づかれちまった。\n\nFalganが俺に逃げろと叫んだから、俺は逃げた。奴がついてきていないと気づいた時には、もうBrillまで半分のところだった。あの勇敢な馬鹿は、俺のために奴らを食い止めようと残ったんだろう。\n\n頼む、俺の友を見つけて、できるなら助けてやってくれ。", nil, nil, 0x58def706, 0xc86dfaf3, 0x7442e1a0, nil, nil, "...mm" },
  [94440] = { "神性の教え", "Venomweb ValeのScarlet CrusadersからScarlet Crusade Attack Plansを奪い、Tyr's WatchのDeathguard Billmuthのところへ戻ってください。", "このScarlet Crusadersどもは、配置命令の入った鞄をよく持ち歩いている。攻撃が来るのはわかっているが、奴らの命令を取り戻せれば、残りのDeathguardに警告して待ち伏せの準備ができる。\n\nお前は明らかに見事なパラディンだ。scarletの獣どもを殺し、奴らの命令書の写しを取り戻して、Deathguard Billmuthのもとへ持っていけ。あとは彼がやってくれる。", nil, nil, 0x58def706, 0x76a3e5d1, 0x03204cbb, nil, nil, "...mm" },
  [94441] = { "神性の教え", "Bandarion Keepの砦にいるDanitha Morrと話す。", "Danitha Morrに私の感謝を伝えてくれ。そしてTyr's Watchのパラディンたちが我々のために果たした務めのことは、Deathguardの皆にも知れ渡るだろうと伝えてほしい。\n\nお前はパラディンとして大いに見込みがある。お前のような者がForsakenの一員であることを誇りに思う。Dark Ladyがお前を見守らんことを、{name}。", nil, nil, 0x58def706, 0x5ae2079a, 0x9f0c78b8, nil, nil, "...mm" },
  [94449] = { "火の呼び声", "Dun MoroghでBruegs Kindlebornを見つけてください。", "お前さんが最後に試されてから、ずいぶん経ったな、{name}。お前さんは忍耐を示した。うむ……だが今こそ、混沌を……破壊を学ぶ時だ。火の呼び声は大きい。その代償を払う覚悟があるなら、火はお前さんに語りかけるだろう。\n\nはるか東の山中にいるBruegs Kindlebornを訪ねよ。奴はSouth Gate Outpostの上の洞窟に住んでおる。お前さんが本当に準備できておるか、奴ならわかるはずだ。", nil, nil, 0x53f3b76b, 0x15200cd4, 0xf3c2198f, nil, nil, "...mm" },
  [94465] = { "火の呼び声", "Torch of the Dormant FlameをLoch ModanのBraldir Ashmantleに届けてください。", "うむ、お前さんには火のトーテムを担うだけの力がある、若いの。だが力だけでは準備ができたことにはならん。\n\nValley o' Kingsの向こう、Loch Modanの岩山に、わしらの聖なる峰のひとつへ通じる隠れた道がある。そこでBraldir AshmantleがShrine o' the Dormant Flameを守っておる。\n\nこの松明を奴のところへ持っていけ。お前さんの意志を示すものだ。祠の火鉢で火を灯して持ち帰れば、トーテムをきちんと授かれるよう取り計らおう。", nil, nil, 0x53f3b76b, 0xef8da8e8, 0x415200cc, nil, nil, "...mm" },
  [94466] = { "火の呼び声", "Fire Tarを1つとReagent Pouchを1つ、Loch ModanのBraldir Ashmantleに届けてください。", "ふん、昔話を聞くためにはるばる来たわけではなかろう、{name}？ お前さんが求めておるのはEternal Flameと火のトーテムだな。\n\nまずは、お前さんの魂を炎に結びつけるsaptaが要る。\n\nわしが作ってやろう。だがそれには2つのものが要る。北のコボルドの洞窟にいるTunnel Rat Geomancersのfire tarと、南の丘に潜むStonesplinter Seerのreagent pouchだ。危険な仕事だが、炎にふさわしい仕事だ。", nil, nil, 0x53f3b76b, 0x1ec23f46, 0x08842bb0, nil, nil, "...mm" },
  [94467] = { "火の呼び声", "Minor Manifestation of Fireを倒し、Shrine of Eternal Flameの頂上にある火鉢にGlowing Emberを置いてください。", "火のsaptaができたぞ、{name}。さあ、炎と向き合え。祠でそれを使い、それから頂上へ登るのだ。そこで精霊が見える。お前さんが仕掛けるまで向こうは打ってこんが、お前さんに見られていることには気づくだろう。\n\n素早く打て、若いの。待てば待つほど、奴は強く燃える。奴が倒れたら、そのglowing embersを取って火鉢に入れろ。松明に火を灯し、火の加護を勝ち取るのだ。", nil, nil, 0x53f3b76b, 0x7d09c623, 0xbfb4503b, nil, nil, "...mm" },
  [94468] = { "火の呼び声", "Torch of Eternal FlameをDun MoroghのBruegs Kindlebornに届けてください。", "松明をしっかりと手に握り、あなたは火鉢に背を向けてLoch Modanを見渡す。風が強まって炎を激しく踊らせると、魂が高揚に引っ張られるのを感じる。\n\nあなたはBruegs Kindlebornを探して、Dun Moroghへ戻る道を下り始める。", nil, nil, 0x53f3b76b, 0x8fb8c297, 0x74b18970, nil, nil, "...mm" },
  [94472] = { "Earth Sapta", "Teo Hammerstormと話して、Earth Saptaをもう一つもらってください。", nil, nil, nil, 0x9c7e1740, 0x0b15db68, nil, nil, nil, "..mmm" },
  [94473] = { "Fire Sapta", "Braldir Ashmantleと話して、Fire Saptaをもう一つもらってください。", nil, nil, nil, 0xe8738c8b, 0x02b1a4f9, nil, nil, nil, "..mmm" },
  [94484] = { "不気味な静寂", "Shadowgale Forestの北東部にいるElegael Thornpawを見つけて話してください。", "少しよろしいですか、{name}。Shadowgale Forestへ向かわれるのですか？ その北東の洞窟にドルイドの集会があります。彼らからの便りを待っているのですが、連絡がずっと途絶えているのです。\n\nBan'aethallが廃墟となり、近頃の騒ぎもあって、何か恐ろしいことが起きたのではと心配でなりません。どうか、行けるのならElegael Thornpawを訪ねて、私を安心させてください。", nil, nil, 0xa432cf89, 0xabfdd6fd, 0xda18a43c, nil, nil, "...mm" },
  [94485] = { "奥方の涙", "Lady's Tear Mossを$N1個集めてください。", "Nightclaw Denにいる仲間たちを救うには、湿布の材料がいくつか必要です。最初の、そして最も大切なものは、Lady's Tearと呼ばれる細長い苔です。ここShadowgaleでは、たいてい木の根元に生えています。\n\nこの苔は消毒作用のある粘り気のある液を出し、開いた傷を閉じるのにうってつけなのです。手の届く範囲でわずかに集めましたが、この森にはもっとあるはずです。\n\nさあ、急いでください。残してきた負傷者たちがまだ生きているなら、たくさん必要になります。", nil, nil, 0x58e6b1d0, 0xfef31217, 0xb28e5c04, nil, nil, "...mm" },
  [94486] = { "束ねるための羽根", "Shadowgale ForestのShadowgale Shrieklingから羽根を$N1枚集めてください。", "湿布に必要なもうひとつの材料は、この森をうろつくShadowgale shrieklingsの羽根です。幼いshrieklingsの羽根は断熱性があり、苔の上にかぶせるのに理想的なのです。この羽根が消毒作用のある樹液の乾燥を防ぎ、風雨からも少しは守ってくれるでしょう。\n\n気をつけてください。shrieklingsは普段はおとなしいのですが、近頃はひどく凶暴になっています。油断すれば、その大きな鉤爪で簡単に腹を裂かれてしまいます。", nil, nil, 0x311c98a1, 0x06470144, 0xcbaac9a6, nil, nil, "...mm" },
  [94487] = { "望まれず、ふさわしからず", "Shadowgale ForestのAl'Aketh FootsoldierとAl'Aketh StormchaserからBloodied Heirloomを$N1個集めてください。", "Al'aketh Cultistsは何の前触れもなく私たちを待ち伏せしましたが、その動機はいまだにわかりません。あの教団員たちの頭が雲でいっぱいなのは知っていましたが、まさかこれほどの残虐さでここZephrasの繊細な均衡を乱すとは思ってもみませんでした。行って、できるだけ多く討ち、家宝を身につけていればそれを奪ってきてください。\n\n<Elegaelは唾を吐く。>\n\n嵐に呪われたこの教団員どもに、shen'doreiと呼ばれる資格などありません。その体は森の獣にくれてやればいい。その灰は風に乗せる価値もありません。", nil, nil, 0x77a04507, 0xec40e0a6, 0x24c43adc, nil, nil, "...mm" },
  [94488] = { "結ぶ絆", "Commander Haalienを倒し、その首をShadowgale ForestのElegael Thornpawに届けてください。", "教団員たちがここにいる理由はいまだにわかりませんが、流血の匂いに混じって覚えのある匂いがします。\n\n私たちの輪のドルイドのひとり、Haalienが何か月も前に姿を消しました。どうやら彼は教団員どもに身を投じたようです。\n\n同胞の血を流せばどうなるか、思い知らせてやってください！ 彼の首を取って、私のところへ持ってきてください。", nil, nil, 0x0b0f4638, 0xa82e2486, 0x89d69201, nil, nil, "...mm" },
  [94489] = { "裏切りの傷", "Nightfang Denに入り、ドルイドを$N1人治療して、Shadowgale ForestでJorel Windsingerを見つけてください。", "湿布ができました。急いで、洞窟にいるドルイドたちのところへ持っていってください。北へ、空き地をすぐ渡ったところです。仲間たちは私よりずっと危うい状態のはずです。きっと傷がひどくて自分で癒やすこともできないでしょう。私たちshen'doreiのドルイドはとても少ないので、ひとつひとつの命が貴重なのです。\n\n行く前に、身勝手なお願いがあります。私の伴侶のJorel Windsingerは、私が出てきた時にはひどい状態でした。どうか、まだ生きていたら、彼の傷を診てあげてください。", nil, nil, 0xf524491f, 0x70ebec30, 0x3d5bdf31, nil, nil, "...mm" },
  [94490] = { "Ripped Missive", "Ripped MissiveをShadowgale ForestのElegael Thornpawに届けてください。", "<Haalienの腕当ての裏に、戦いで少し破れて血に染まった書き付けが挟まっている。ドルイドの住処を襲った教団員たちの動機について、役に立つ情報が書かれているようだ。Elegaelならこの情報に関心を持つだろう。>", nil, nil, 0xab8b8528, 0x38e9ba67, 0x3f35d6c4, nil, nil, "...mm" },
  [94491] = { "巣穴の運命", "ValannarのLotheluumに書簡を渡し、何が起きたかを伝えてください。", "教団に情報を流している内通者が、Valanaarのどこかに潜んでいるようです。私はとても旅のできる状態ではありませんが、ここで何があったのかをLotheluumに知らせなければなりません。\n\nもういない者たちの運命も、彼は知るべきです。あなたのおかげで、ここから先はなんとか私たちで対処できると思います。もっとも、損害はすでに出てしまいましたが。\n\nどうか急いで行ってください、{name}。いつかまた道が交わることを願っています。それまで、私には倒すべき教団員たちがいますから。", nil, nil, 0xef28fcc3, 0x2bc67d95, 0xd75bb584, nil, nil, "...mm" },
  [94493] = { "無駄な犠牲", "Shadowgale Forestの北東部にいるElegael Thornpawと話してください。", "よかった、私たちの知らせはLotheluumに届いたのですね。待って、残りの援軍はどこです？ まさか送られてきたのはあなただけではないでしょう？\n\n<あなたが事情を説明すると、Elegaelは青ざめる。>\n\nでは、知らせはValanaarには届かなかったのですね。それなら私たちは本当に窮地にあります。\n\n<Elegaelは深くため息をつき、それから決意を固めた表情になる。>\n\nならば、私たちだけで対処するしかありません。一刻を争います。", nil, nil, 0xaf28bd4e, 0xfc76d336, 0x18628a43, nil, nil, "...mm" },
  [94494] = { "水の呼び声", "Loch ModanでNorric Lochthaneを見つけてください。", "お前さんが最後に試されてから長い時が経ったな、{name}。これまでの修行でお前さんは忍耐を示してきた。だが今こそ、水の清らかさについて学ぶ時が来た。\n\nLoch ModanにいるNorric Lochthaneを訪ねよ。湖の北西の岸沿い、Stonewrought Damの南におる。そこの穴蔵小屋で奴に会えるだろう。幸運を祈るぞ、{name}。", nil, nil, 0x1f0e11aa, 0xa614e79c, 0xf11bb23d, nil, nil, "...mm" },
  [94495] = { "水の呼び声", "WetlandsでHervdana Saegrundを見つけてください。", "水について学ぶべき真実がひとつあるとすれば、それはこれだ。水とは再生を意味する。水は石を削り、汚れを清め、疲れた者を癒やす。だが、それは清らかな時だけだ。汚されれば、触れるものすべてを台無しにする。\n\n水のsaptaを求めるなら、WetlandsのHervdana Saegrundを訪ねよ。あの娘の一家は南の滝の下の洞窟に住んでおる。\n\nさあ行け、川に追い越されるなよ。", nil, nil, 0x1f0e11aa, 0xadc7f213, 0xadd95e2e, nil, nil, "...mm" },
  [94497] = { "水の呼び声", "Hervdanaの洞窟の下にある滝の底でEmpty Brown Waterskinを満たし、Wetlandsにいる彼女のもとへ持ち帰ってください。", "あら、saptaを求めて来たってわけね？ それじゃよく聞いて、あんた。理解を得てsaptaを手に入れるには、さまざまな姿の水を探さなきゃならないの。見本を集めながら、目をしっかり開けておくこと。水を守る獣たち、水が潤す土地、そして水がどう命を変えるかをよく見るのよ。\n\nまずは簡単なところから。滝の根元の、真水と汽水が混じるところでこの水袋を満たしてきて。さあ行って、沼には気をつけてね。", nil, nil, 0x1f0e11aa, 0xa3d8f378, 0x4ed51e9b, nil, nil, "...mm" },
  [94499] = { "水の呼び声", "Nightcrawler Murlocsの近くにあるStonewatch FallsでEmpty Red Waterskinを満たし、WetlandsのHervdana Saegrundのところへ戻ってください。", "そうそう、RedridgeはLake Everstillからたっぷり水を飲んでるけど、その水がStonewatch Fallsを流れ落ちる頃には、何かが染み込んでるの。あそこのmurlocはでかくてねじれた乱暴者よ。ここやLochで見かけるのとは違うわ。町の人たちにとって幸いなことに、あいつらは滝の根元から出てこないけどね。\n\n水を少し汲んできて。あの古い砦の近くの水を汚してるのが魔法なのか、毒なのか、それとももっとひどい何かなのか、突き止めてやろうと思ってるの。", nil, nil, 0x1f0e11aa, 0x6ccca7b4, 0xa2cb5a4a, nil, nil, "...mm" },
  [94500] = { "水の呼び声", "AshenvaleのAstranaarの水でUnfilled Blue Waterskinを満たし、WetlandsのHervdana Saegrundのところへ戻ってください。", "この水袋を持って、Ashenvaleの深い緑陰へ旅してきて。Astranaarは、穢れに触れていない水に抱かれるようにしてあるの。湖の底には遺跡が散らばっていて、遠い昔の時代をうかがわせるわ。その湖から見本を汲んできて。清らかで、古くて、もしかしたら魔法がかかっているかもしれない水よ。\n\nそれが、あんたをNorricのところへ送り返す前に必要な最後の水なの。\n\nMenethilでAuberdine行きの船に乗って。途中でSouthshoreに寄るから。\n\nそれと、気をつけてね……あの森には目があって、その目はまばたきしないのよ。", nil, nil, 0x1f0e11aa, 0x76aef756, 0x67bea8a4, nil, nil, "...mm" },
  [94501] = { "水の呼び声", "Vial of Purest WaterをLoch ModanのNorric Lochthaneに届けてください。", "水のトーテムの儀式で報いる前に、Norricはあんたにもうひとつ仕事を頼むはずよ。私が渡した水の小瓶は、その仕事が何であれ必要になるの。さあ行って、彼を見つけて。またいつか会いましょう。", nil, nil, 0x1f0e11aa, 0x0d508544, 0x58506c33, nil, nil, "...mm" },
  [94502] = { "水の呼び声", "WestfallのStendel's Pondの汚染を浄化してください。\n終わったらLoch ModanのNorricのところへ戻ってください。", "Westfallの、Moonbrookの外れにStendel's Pondがある。かつては清らかな泉だったが、今は闇の力に汚されておる。そこの精霊たちは黙り込んでしまった。\n\nお前さんはその水を汚す穢れと向き合わねばならん。そいつの腕輪と、Hervdanaの薬の最後の数滴を持って、祠に置け。そうすれば、清められた真の精霊が呼び出される。そいつと話し、学べることを学ぶのだ。\n\n事を成し遂げた証を持ってくれば、トーテムを授けよう。", nil, nil, 0x1f0e11aa, 0x5b8fcaa6, 0xcfb8681c, nil, nil, "...mm" },
  [94503] = { "水の呼び声", "WestfallにいるMinor Manifestation of Waterと話す。", "最後の言葉が唇を離れると同時に、光がほとばしる。水が霧へと変わるシューという音は静寂の中に消えていき、周りの堕落した精霊たちがほどけていくにつれ、あなたの感覚は揺らぐ。その本質は風に舞う灰のように散っていく。", nil, nil, 0x1f0e11aa, 0x2cab5030, 0x31813519, nil, nil, "...mm" },
  [94505] = { "水の呼び声", "Shard of WaterをLoch ModanのNorric Lochthaneに届ける。", "shardを取れ。shardを取り、命を与えよ。\n\n命を与え、理解せよ。水は命だと理解せよ……穢れは命を止める。\n\nお前は水の力で命を守り、与える。", nil, nil, 0x1f0e11aa, 0x038a8a5c, 0x1bc4c72c, nil, nil, "...mm" },
  [94559] = { nil, "Shen'dar HighlandsでAl'Aketh Turncoatを探し出して下さい。", "Al'Akethの中に裏切り者がいる。奴は教団がこの島で何を企んでいるのか本当のところを知っていると言い、こちらに寝返りたがっているが、身の安全が保証されなければ応じないそうだ。\n\nその離反者はValanaarのすぐ北西、高地に入ってすぐの家に隠れている。誰にも気づかれずにそこへ行き、裏切り者を見つけ出し、話を聞いて我々のもとへ連れ帰れる者が必要だ。罠かもしれないが、この情報が本人の言うとおり重要なら、多少の危険を冒す価値はある。", nil, nil, nil, 0x1c0f7bd4, 0x820b6736, nil, nil, "m..mm" },
  [94568] = { "教団の真の計画", "Talaanis Shadowsongと話し、会話を見守ってください。", "あの裏切り者は教団の企みを明らかに恐れていました。寝返って私たちの助けを求めるほどに。彼が死に、秘密を墓まで持っていってしまったのは本当に残念です。\n\n次にどうすべきかを決めるため、このことをさらに話し合わなければなりません。", nil, nil, 0xb5a1a1cb, 0x8a14b2e2, 0xff8479a4, nil, nil, "...mm" },
  [94616] = { "Water Sapta", nil, nil, nil, nil, 0xcd2fb34a, nil, nil, nil, nil, ".mmmm" },
  [94638] = { "力と慈悲", "Shen'dar HighlandsでUr'endraを見つけて倒してください。", "そなたは力の姿を身につけることを望んで我のもとへ来たのだな。そなたに頼みたいことがある。我が心には重いことだが。\n\n我が伴侶Ur'endraは狂気に呑まれ、己の同胞を襲い始めた。風の魔法を失い、多くの生き物が我を失いつつある……Ur'endraも例外ではない。彼女はここから西、Shen'dar HighlandsとGustberry Lowlandsの境にある断崖の洞窟を住処にしている。\n\n彼女の苦しみを終わらせてくれ。さすれば我が祝福を授けよう。", nil, nil, 0x063a7e36, 0xbdfde440, 0x50f1cf45, nil, nil, "...mm" },
  [94773] = { "神の恩寵", nil, nil, nil, nil, 0x4199a5e1, nil, nil, nil, nil, ".mmmm" },
  [94774] = { "神の恩寵", "StormwindのHigh Priestess Laurenaと話してください。", "あなたは上の方々の目に留まったのですよ、{name}。できるだけ早くStormwindのCathedral of Lightへ来てほしいとのことです。どうやら、あなたはすでに自分を証明したと考えていて、さらに修行を進める準備ができているようです。着いたらHigh Priestess Laurenaを探してください。彼女がさらに導いてくれるでしょう。幸運を。光があなたと共にありますように。", nil, nil, 0x4199a5e1, 0x8de762b6, 0xe9bfda0e, nil, nil, "...mm" },
  [94775] = { "神の恩寵", "StormwindのHigh Priestess Laurenaと話してください。", "Eluneの祝福を、善き{race}よ。今日もあなたの光があなたを見出し、よく守ってくれますように。\n\n少し前に、あなたの側のプリーストがあなたを探してここへ来ました。できるだけ早くCathedral of Lightへ戻り、High Priestess Laurenaと話すようにとのことでした。それほどの注目を集めるとは、よく励んできたのですね。ここに長居はしない方がいいでしょう。あなたの同胞があなたを必要としています。", nil, nil, 0x4199a5e1, 0x8de762b6, 0x93d8c9e5, nil, nil, "...mm" },
  [94776] = { "神の恩寵", "StormwindのHigh Priestess Laurenaと話してください。", "Stormwindへ向かう時が来たよ、{name}。Cathedral of LightのHigh Priestess Laurenaがあんたと話したいってさ。High Priestessがじきじきに呼ぶなんて、よほどいいことか、よほど悪いことに違いないけど、あんたはうまくやってきただけだろうし、話したいってのはいいことだと思うよ。\n\nでも、このへんでぐずぐずしてちゃだめだよ。俺ならできるだけ早く向かうね。", nil, nil, 0x4199a5e1, 0x8de762b6, 0x0e82ce63, nil, nil, "...mm" },
  [94777] = { "神の恩寵", "StormwindのHigh Priestess Laurenaと話して下さい。", "ほんの少し前、あなたの同胞のプリーストがあなたを探してここに来ていましたよ、{race}。もしあなたに会ったら、Cathedral of Lightへ向かうよう伝えてほしいとのことでした。とても大事な用だと言っていましたが、私があなたなら、あまり心配はしません。あの方の様子は明るいものでした……まるで良い知らせであるかのように。私なら、そこへ向かうのにあまり時間はかけませんね。\n\nEluneの加護がありますように、善き{race}よ。", nil, nil, 0x4199a5e1, 0x8de762b6, 0x1cfc2115, nil, nil, "...mm" },
  [94778] = { "神の恩寵", "StormwindのHigh Priestess Laurenaと話してください。", "Stormwindであなたが必要とされているぞ、{name}。そこのHigh PriestessのLaurenaが、修行の次の段階にふさわしいことを証明する時だと言っている。向かうのにあまり時間をかけるな。彼女は街の中心にあるCathedral of Lightにいる。よろしく伝えてくれ。そして、その使命にどれほどふさわしいかを証明してこい。光があなたと共にあらんことを、{name}。", nil, nil, 0x4199a5e1, 0x8de762b6, 0x8ea469d6, nil, nil, "...mm" },
  [94779] = { "神の恩寵", "StormwindのHigh Priestess Laurenaと話して下さい。", "Eluneに、そしてあなたの光に賛美を、{name}。\n\nこの頃になると、我々の教団の多くの者はEluneへの信仰を映した能力を学びます。私の知識が確かなら、あなたの教団でも同じことが言えるはずです。\n\nDarnassusでの用事が済んだら、さらなる修練のために、あなたの教団のHigh Priestessesの一人を訪ねるとよいでしょう。", nil, nil, 0x4199a5e1, 0x8de762b6, 0x9d972e4f, nil, nil, "...mm" },
  [94792] = { "獣を手なずける", "Taming Rodを使ってRockhide Boarを手なずけてください。技を練習したら、Taming RodをJosephine Carsonに返してください。", "多くのハンターは動物の相棒を連れて旅することを好みます。獣がそばにいれば、どれほど危険な状況でも生き延びられることがわかるでしょう。よく言うように、友がいれば何事もたやすくなるものです。けれども、動物の相棒を得るには慎重さが必要です。自然の均衡は繊細で、常に尊重されなければなりません。\n\nこのTaming Rodを持って森へ行きなさい。これを使えばRockhide Boarを手なずけ、ハンターとしての技を磨けるでしょう。", nil, nil, 0xecd97a9a, 0x19efabbc, 0x69a91737, nil, nil, "...mm" },
  [94793] = { "獣を訓練する", "GoldshireのIsaac Chanと話してください。", "あなたはペットを手なずける力を得ましたが、それを訓練する技も身につけなければなりません。それには、生涯を森で過ごしてきたIsaac Chanに勝る者はいません。彼が新しいペットを訓練する力を授けてくれるでしょう。\n\n風と共に行きなさい、若き{class}よ。", nil, nil, 0xdbeedc0e, 0xf8c4ebf2, 0x4bc880b0, nil, nil, "...mm" },
  [94817] = { "惑わしの閃光", nil, nil, nil, nil, 0xd8782324, nil, nil, nil, nil, ".mmmm" },
  [94818] = { "Contingency Plan", nil, nil, nil, nil, 0x584b30b7, nil, nil, nil, nil, ".mmmm" },
  [94819] = { "Contingency Plan", "IronforgeのHigh Priestess Mimsと話す。", "{name}、あなたのHigh Priestess MimsがIronforgeであなたとの面会を望んでいます。急いでください、賢い友よ。次の試練がすぐそこまで迫っています。あなたの種族独自の儀式に立ち会えればと願うのですが、私の居場所はここです。それでも、旅路に光が共にあらんことを。街に着いたら、MimsはまだMystic Wardにいるはずです。彼女が待っています。", nil, nil, 0x584b30b7, 0x656c5f67, 0xf8b55805, nil, nil, "...mm" },
  [94820] = { "非常時の計画", "IronforgeのHigh Priestess Mimsと話して下さい。", "あなたの種族は本当に賢いですね、{name}。あなたがたを盟友と呼べることを誇りに思います。そして日が沈むたびに、あなたとあなたの同胞は故郷の街を取り戻す日に近づいていますが、亡命先で家族を守るという重荷も背負っています。故郷への思いは、さぞ重くのしかかっていることでしょう。\n\nつい最近、Ironforgeから知らせが届きました。そこへ戻り、Mystic WardのHigh Priestess Mimsと話すようにとのことです。彼女を待たせてはいけませんよ。Eluneがあなたの旅を導いてくれますように。", nil, nil, 0x584b30b7, 0x656c5f67, 0xfc0c8df4, nil, nil, "...mm" },
  [94821] = { "惑わしの閃光", "IronforgeのHigh Priestess Mimsと話してください。", "最近、プリーストがひとり、あなたを探して私たちの広間を訪れました、若き{race}よ。あなたを見つける使命を帯びていて、できるだけ早くIronforgeのHall of Mysteriesへ戻るように、とのことでした。着いたらHigh Priestess Mimsを訪ねてください。詳しいことは彼女が教えてくれるでしょう。\n\n光があなたと共にありますように、{name}。", nil, nil, 0xd8782324, 0x656c5f67, 0xb61e2669, nil, nil, "...mm" },
  [94822] = { "惑わしの閃光", "IronforgeのHigh Priestess Mimsと話してください。", "あなたは上の方々の目に留まったのですよ、{name}。できるだけ早くIronforgeのHall of Mysteriesへ来てほしいとのことです。どうやら、あなたはすでに自分を証明したと考えていて、さらに修行を進める準備ができているようです。着いたらHigh Priestess Mimsを探してください。彼女がさらに導いてくれるでしょう。幸運を。光があなたと共にありますように。", nil, nil, 0xd8782324, 0x656c5f67, 0x591115c6, nil, nil, "...mm" },
  [94823] = { "惑わしの閃光", "IronforgeのHigh Priestess Mimsと話してください。", "Eluneの祝福を、善き{race}よ。今日もあなたの光があなたを見出し、よく守ってくれますように。\n\n少し前に、あなたの側のプリーストがあなたを探してここへ来ました。できるだけ早くHall of Mysteriesへ戻り、High Priestess Mimsと話すようにとのことでした。それほどの注目を集めるとは、よく励んできたのですね。ここに長居はしない方がいいでしょう。あなたの同胞があなたを必要としています。", nil, nil, 0xd8782324, 0x656c5f67, 0xf4f34293, nil, nil, "...mm" },
  [94824] = { "惑わしの閃光", "IronforgeのHigh Priestess Mimsと話してください。", "Stormwindへ向かう時が来たよ、{name}。Hall of MysteriesのHigh Priestess Mimsが、話しに来いってさ。High Priestessがじきじきに呼ぶなんて、よほどいいことか、よほど悪いことに違いないけど、あんたはうまくやってきただけだろうし、話したいってのはいいことだと思うよ。\n\nでも、このへんでぐずぐずしてちゃだめだよ。俺ならできるだけ早く向かうね。", nil, nil, 0xd8782324, 0x656c5f67, 0xfdd4362c, nil, nil, "...mm" },
  [94825] = { "Confounding Flash", "IronforgeのHigh Priestess Mimsと話す。", "ついさっき、あなたの教団のプリーストの一人があなたを探しにここへ来ました、{race}。もし私があなたに会ったら、Hall of Mysteriesへ行くよう伝えてほしいと。とても大切なことだと言っていましたが、私ならあまり心配はしません。彼の様子は明るく……まるで良い知らせのようでした。私があなたなら、あまり時間をかけずに向かいますね。\n\nEluneのご加護を、善き{race}よ。", nil, nil, 0xd8782324, 0x656c5f67, 0xa819c88b, nil, nil, "...mm" },
  [94826] = { "惑わしの閃光", "IronforgeのHigh Priestess Mimsと話してください。", "Eluneに、そしてあなたの光に讃えあれ、{name}。\n\nこの頃になると、私たちの教団の多くはEluneへの信仰を映す力を学びます。私の知る限り、あなたの教団でも同じことが言えるはずです。\n\nDarnassusでの用事が済んだら、さらなる修行のためにあなたのHigh Priestessを訪ねるとよいでしょう。", nil, nil, 0xd8782324, 0x656c5f67, 0x560c66c6, nil, nil, "...mm" },
  [94863] = { "獣を手なずける", "Taming Rodを使ってGray Forest Wolfを手なずけてください。技を練習したら、Taming RodをJosephine Carsonに返してください。", "あなたはもうボアの手なずけ方を身につけましたね。では次の教えに進みましょう。森にはもっと獰猛な相棒がいます。慎重にやれば、その信頼を得られるでしょう。\n\nこのTaming Rodを持って、Gray Forest Wolfを探しなさい。忘れないで、自然の均衡は尊重されなければなりません。ハンターとしての技をもう一度示してください。", nil, nil, 0xecd97a9a, 0x18dda32c, 0x8619c636, nil, nil, "...mm" },
  [94864] = { "獣を手なずける", "Taming Rodを使ってYoung Forest Bearを手なずけてください。技を練習したら、Taming RodをJosephine Carsonに返してください。", "あなたはボアと狼を手なずけて自分を証明しました。いよいよ最後の試練です。Elwynnの均衡は、敬意と技にかかっています。このTaming Rodを持って、Young Forest Bearを探しなさい。最も強大な相棒の信頼さえも得られることを示してください。\n\nこの教えを終えれば、獣との心の通い合いがより深まるでしょう。", nil, nil, 0xecd97a9a, 0x4d82c2d9, 0x7dc729d2, nil, nil, "...mm" },
  [94896] = { "難民への支援", "Ban'aethalの廃墟からAbandoned Belongingsを$N1個集めてください。", "頼りになりそうな冒険者さんですね。もしかしてShadowgale Forestへ向かうところですか？ Ban'aethalはその森の奥にあります。私たちは皆そこから来たのです。\n\n<Ealaaneは他の避難民たちを指し示す。>\n\n最近、Ban'aethalが空へ落ち始めたので、私たちは避難しなければなりませんでした。真夜中に、突然のことでした。もしそちらへ向かうなら、残してきた持ち物を探していただけませんか？ 森も村も危険すぎて、今の私たちには戻れないのです。", nil, nil, 0x0098f2fc, 0x0e6b1138, 0x187b86ed, nil, nil, "...mm" },
  [94897] = { "愛する者の運命", "Ruins of Ban'aethalでResaanを見つけてください。", "Ban'aethalへ旅するのなら、身勝手なお願いがあります。私の愛しい人、Resaanは……もうこの世にいないと思うのです。私が行かないでと懇願したのに、彼は物資を取りに戻ろうとしました。もう一週間以上になり、最悪の事態を恐れています。\n\nどうか、彼を見つけたら家に連れて帰ってください。もし亡くなっていたら、どうか彼の家宝を持ってきてください。", nil, nil, 0xb884fe2f, 0xf98283dc, 0x21413fb8, nil, nil, "...mm" },
  [94898] = { nil, "Wind Hollowを$N1体倒す。", "あの運命の夜、私たちの故郷が空へと崩れ落ちはじめた時、まるで精霊たちが私たちを飲み込もうと待ち構えていたかのようでした。逃げている最中に風の精霊が現れはじめ、恐ろしいことに、逃げ惑う生存者たちを襲いはじめたのです。\n\n多くの村人を空に奪われましたが、あの風の精霊たちの容赦ない怒りによって失った者はもっと多いのです。村が空へ落ちたせいなのかは分かりませんが、奴らは極めて危険です。\n\nもしできるなら、どうか奴らを鎮めてください。", nil, nil, nil, 0x131d9d41, 0xb6b72cef, nil, nil, "m..mm" },
  [94901] = { "跳ねる助っ人たち", "Gustjumperの蛙を$N1匹集める。", nil, nil, nil, 0x948903fd, 0x0d6a2d17, nil, nil, nil, "..mmm" },
  [94902] = { "Valanaarの銘酒", "$N1個のブドウを集める。", nil, nil, nil, 0xeeccf2b3, 0xf13640b3, nil, nil, nil, "..mmm" },
  [94911] = { "自然の子", "Thunder BluffのTurak Runetotemと話してください。", "ごきげんよう、若き{race}よ。あなたにはドルイドの術の大きな素質が見えます。Thunder Bluffの街に、Turak Runetotemという名の、話をしておくとよい方がいます。彼が、KalimdorにあるCenarion Circleの拠点、Moongladeへ行く方法を教えてくれるでしょう。\n\nあなたはそこで歓迎され、Circleのドルイドたちがその知識をあなたに授けてくれるでしょう。\n\nあなたの同胞の言い方を借りれば……風の祝福と共に行きなさい、若き者よ。あなたの冒険に幸運がありますように。", nil, nil, 0xb806d7b4, 0x724e1ed0, 0x87d83a15, nil, nil, "...mm" },
  [94912] = { "自然の子", "StormwindのSheldras Moontreeと話してください。", "ごきげんよう、若き{class}よ。\n\nCenarion Circleについて聞いたことはありますか？ おそらくないでしょうね。彼らは自然を探究し、ドルイドの術を修める古い結社で、あなたとよく似た者たちです。Stormwindの街に、Sheldras Moontreeという名のナイトエルフがいます。彼が、KalimdorにあるCenarion Circleの拠点、Moongladeという場所へ行く方法を教えてくれるでしょう。\n\nさあ、行きなさい。故郷を救いたいのなら、学ぶべきことはたくさんあります。", nil, nil, 0xb806d7b4, 0x59f95b86, 0xfd0dcca7, nil, nil, "...mm" },
  [94913] = { "Moonglade", "呪文「Teleport: Moonglade」を使ってMoongladeへ移動してください。到着したら、Nighthavenの村にいるDendrite Starblazeと話してください。", "すべてのドルイドはMoongladeの聖地に迎えられます。Moongladeの守護者であるKeeper Remulosが、そこで眠りにつくすべてのドルイドを見守っています。そこへ自分を運ぶ呪文を教えましょう。Moongladeの知恵や安らぎを求める時は、いつでもそれを唱えなさい。\n\nここAzerothでの最初の教えとして、Moongladeへ旅し、NighthavenのDendrite Starblazeと、あなたが今歩んでいる道について話しなさい。幸運を、若きドルイドよ。", nil, nil, 0xaeb97c8b, 0xf8085429, 0x78dcadda, nil, nil, "...mm" },
  [94914] = { "Moonglade", "呪文「Teleport: Moonglade」を使ってMoongladeへ移動してください。到着したら、Nighthavenの村にいるDendrite Starblazeと話してください。", "すべてのドルイドはMoongladeの聖地に迎えられます。Moongladeの守護者であるKeeper Remulosが、そこで眠りにつくすべてのドルイドを見守っています。そこへ自分を運ぶ呪文を教えましょう。Moongladeの知恵や安らぎを求める時は、いつでもそれを唱えなさい。\n\nここAzerothでの最初の教えとして、Moongladeへ旅し、NighthavenのDendrite Starblazeと、あなたが今歩んでいる道について話しなさい。幸運を、若きドルイドよ。", nil, nil, 0xaeb97c8b, 0xf8085429, 0x78dcadda, nil, nil, "...mm" },
  [94946] = { "魔法都市Dalaran", "Zephras Isleからスカイカッター船に乗ってDalaran Cityへ向かい、到着したらDanaaris Stargaleと話してください。", "我々の中で最初にAzerothの地を踏むのは私のつもりだったが、カルトをめぐる最近の出来事で予定が変わった。そのため、しばらくはここValanaarに残ることになる。だが心配はいらない。Dalaranでは何人ものメイジが我らの民の到着を待っている。我々がここで態勢を整える間、君にはAzerothを探索してほしい。必要な時には、君のような者たちに声をかける。\n\n準備ができたら、このロッジのすぐ外の桟橋へ行き、そこのskycutter船に乗ってくれ。", nil, nil, 0x26c38851, 0x00903656, 0xb66f8dd9, nil, nil, "...mm" },
  [94947] = { "Azerothへようこそ", "Skyborne Portalを使ってStormwindへ行き、Stormwind KeepのBolvar Fordragonに報告してください。", "この下の世界は広い。我々の同胞にも外へ広がって探索を始めてもらう必要がある。そこであなたの出番だ。\n\nKirin Torは、志を同じくする国々の「Alliance」の一員だ。その同盟の事実上の中心は、南にあるStormwindの街だ。Elaadrinから、Stormwindへ旅してそこの摂政、Bolvar Fordragonという人間と会う者を探すよう頼まれている。\n\n準備ができたら、Kirin Torのメイジたちが、High OrderがStormwindへ行くための特別なポータルを用意してくれている。", nil, nil, 0x2f003d6f, 0x9e17660a, 0xa0e7b1fe, nil, nil, "...mm" },
  [94978] = { "獣を手なずける", "Taming Rodを使って水辺にいるWindsong Crawlerを手なずけてください。\n技を練習したら、Taming RodをValanaarのQuel'ana Quickgaleに返してください。", "どのハンターも、獣と主人の絆を学ぶことから始めます。これがあなたの最初の試練です。いずれあなたは世界の隅々の生き物を手なずけることになるでしょうが、今はここZephrasの川や湖から始めましょう。\n\nこのTaming Rodを持って、Windsong Crawlerを探しなさい。\n\nその信頼を得られることを示し、真の熟達への道を歩み始めてください。", nil, nil, 0xecd97a9a, 0xc2ec4aaf, 0x97c66def, nil, nil, "...mm" },
  [94979] = { "獣を手なずける", "Taming Rodを使ってGustberry LowlandsのOrnery Galestriderを手なずけてください。\n技を練習したら、Taming RodをValanaarのQuel'ana Quickgaleに返してください。", "あなたは川のcrawlerを手なずけられることを示しました。今度は開けた土地で腕を試す時です。Zephrasの平原には、風のように駆ける誇り高き翼のハンター、Galestriderの鳴き声が響いています。\n\nこのTaming Rodを持って、それを探しなさい。低地へ旅して、その信頼を得てください。\n\nこの先の試練に備えができていることを示しなさい。", nil, nil, 0xecd97a9a, 0x116b4c2f, 0x7fbaa677, nil, nil, "...mm" },
})
